) ON COMMIT DROP;

INSERT INTO m225_art VALUES
(0,0,$m225$الديباجة$m225$,$m225$الجريدة الرسمية - العدد 6 (مكرر) فى 15 فبراير سنة 2005
قانون رقم 3 لسنة 2005
بإصدار قانون حماية المنافسة
ومنع الممارسات الاحتكارية
باسم الشعب
رئيس الجمهورية
قرر مجلس الشعب القانون الآتى نصه ، وقد أصدرناه :$m225$,'c5f491e3912a2852aee3210ea416a42c'),
(1,-1,$m225$المادة الأولى إصدار$m225$,$m225$يعمل بأحكام القانون المرافق فى شأن حماية المنافسة ومنع الممارسات الاحتكارية .$m225$,'0ada3a0dbfc3d68ae95ea9c9e2e487c0'),
(2,-1,$m225$المادة الثانية إصدار$m225$,$m225$رئيس مجلس الوزراء هو الوزير المختص بتطبيق أحكام القانون المرافق .$m225$,'a402b9bf0291d11e4eb99a1ad8f16862'),
(3,-1,$m225$المادة الثالثة إصدار$m225$,$m225$تصدر اللائحة التنفيذية للقانون المرافق بقرار من رئيس مجلس الوزراء ، وذلك خلال شهر من تاريخ العمل بهذا القانون .$m225$,'a95b387770c4e3ee77a90481d4beb975'),
(4,-1,$m225$المادة الرابعة إصدار$m225$,$m225$ينشر هذا القانون فى الجريدة الرسمية ، ويعمل به بعد ثلاثة أشهر من اليوم التالى لتاريخ نشره .
يبصم هذا القانون بخاتم الدولة ، وينفذ كقانون من قوانينها .
صدر برئاسة الجمهورية فى 6 المحرم سنة 1426 هـ
( الموافق 15 فبراير سنة 2005 م ) .
حسنى مبارك$m225$,'ed5a20f9ea98768085aa89f30ba4295b'),
(1,0,$m225$المادة 1$m225$,$m225$تكون ممارسة النشاط الاقتصادى على النحو الذى لا يؤدى إلى منع حرية المنافسة أو تقييدها أو الإضرار بها ، وذلك كله وفق أحكام القانون .$m225$,'d1858e53ff06ee56dc6330ce16b0bacf'),
(2,0,$m225$المادة 2$m225$,$m225$فى تطبيق أحكام هذا القانون يقصد بالكلمات الآتية المعنى المبين قرين كل منها :
( أ ) الأشخاص : الأشخاص الطبيعيون والأشخاص الاعتبارية ، والكيانات الاقتصادية ، والاتحادات ، والروابط والتجمعات المالية وتجمعات الأشخاص على اختلاف طرق تأسيسها ، وغيرها من الأطراف المرتبطة على النحو الذى تحدده اللائحة التنفيذية بما يتفق مع أهداف وأحكام هذا القانون .
( ب ) المنتجات : السلع والخدمات .
( جـ ) الجهاز : جهاز حماية المنافسة ومنع الممارسات الاحتكارية المنشأ طبقًا لأحكام هذا القانون .
( د ) المجلس : مجلس إدارة جهاز حماية المنافسة ومنع الممارسات الاحتكارية .$m225$,'b5506244fbf54faeee7948fac0b43f40'),
(3,0,$m225$المادة 3$m225$,$m225$السوق المعنية فى تطبيق أحكام هذا القانون هى السوق التى تقوم على عنصرين هما المنتجات المعنية والنطاق الجغرافى . وتكون المنتجات المعنية تلك التى يعد كل منها بديلاً عمليًا وموضوعيًا عن الآخر ، ويعنى النطاق الجغرافى منطقة جغرافية معينة تتجانس فيها ظروف التنافس مع أخذ فرص التنافس المحتملة فى الاعتبار ، وذلك كله وفقًا للمعايير التى تبينها اللائحة التنفيذية بما يتفق مع أهداف وأحكام هذا القانون .$m225$,'b83cbe43c01bc3a98da061deb5e56bfb'),
(4,0,$m225$المادة 4$m225$,$m225$السيطرة على سوق معنية فى تطبيق أحكام هذا القانون هى قدرة الشخص الذى تزيد حصته على (25%) من تلك السوق على إحداث تأثير فعال على الأسعار أو حجم المعروض بها دون أن تكون لمنافسيه القدرة على الحد من ذلك .
ويحدد الجهاز حالات السيطرة وفقًا للإجراءات التى تبينها اللائحة التنفيذية لهذا القانون .$m225$,'29b2b7cba47a0559397ef92dea7c7f47'),
(5,0,$m225$المادة 5$m225$,$m225$تسرى أحكام هذا القانون على الأفعال التى ترتكب فى الخارج إذا ترتب عليها منع حرية المنافسة أو تقييدها أو الإضرار بها فى مصر والتى تشكل جرائم طبقا لهذا القانون .$m225$,'440359e5b1aeead109ac2d04f50e219f'),
(6,0,$m225$المادة 6$m225$,$m225$يحظر الاتفاق أو التعاقد بين أشخاص متنافسة فى أية سوق معينة إذا كان من شأنه إحداث أى مما يأتى :
( أ ) رفع أو خفض أو تثبيت أسعار البيع أو الشراء للمنتجات محل التعامل .
( ب ) اقتسام أسواق المنتجات أو تخصيصها على أساس من المناطق الجغرافية أو مراكز التوزيع أو نوعية العملاء أو السلع أو المواسم أو الفترات الزمنية .
( جـ ) التنسيق فيما يتعلق بالتقدم أو الامتناع عن الدخول فى المناقصات والمزايدات والممارسات وسائر عروض التوريد .
( د ) تقييد عمليات التصنيع أو التوزيع أو التسويق أو الحد من توزيع الخدمات أو نوعها أو حجمها أو وضع شروط أو قيود على توفيرها .$m225$,'24cb9b432f4f9d289f2fac583a26f216'),
(7,0,$m225$المادة 7$m225$,$m225$يحظر الاتفاق أو التعاقد بين الشخص وأى من مورديه أو من عملائه ، إذا كان من شأنه الحد من المنافسة .$m225$,'64bd93b4ef0ab7a189eaae6d801b6c1a'),
(8,0,$m225$المادة 8$m225$,$m225$يحظر على من تكون له السيطرة على سوق معنية القيام بأى مما يأتى :
( أ ) فعل من شأنه أن يؤدى إلى عدم التصنيع أو الإنتاج أو التوزيع لمنتج لفترة أو فترات محددة .
( ب ) الامتناع عن إبرام صفقات بيع أو شراء منتج مع أى شخص أو وقف التعامل معه على نحو يؤدى إلى الحد من حريته فى دخول السوق أو الخروج منه فى أى وقت .
( جـ ) فعل من شأنه أن يؤدى إلى الاقتصار على توزيع منتج دون غيره ، على أساس مناطق جغرافية أو مراكز توزيع أو عملاء أو مواسم أو فترات زمنية وذلك بين أشخاص ذوى علاقة رأسية .
( د ) تعليق إبرام عقد أو اتفاق بيع أو شراء لمنتج على شرط قبول التزامات أو منتجات تكون بطبيعتها أو بموجب الاستخدام التجارى للمنتج غير مرتبطة به أو بمحل التعامل الأصلى أو الاتفاق .
( هـ ) التمييز بين بائعين أو مشترين تتشابه مراكزهم التجارية فى أسعار البيع أو الشراء أو فى شروط التعامل .
( و ) الامتناع عن إنتاج أو إتاحة منتج شحيح متى كان إنتاجه أو إتاحته ممكنة اقتصاديا .
( ز ) أن يشترط على المتعاملين معه ألا يتيحوا لشخص منافس له استخدام ما يحتاجه من مرافقهم أو خدماتهم ، رغم أن إتاحة هذا الاستخدام ممكن اقتصاديا .
( ح ) بيع منتجات بسعر يقل عن تكلفتها الحدية أو متوسط تكلفتها المتغيرة .
( ط ) إلزام مورد بعدم التعامل مع منافس .
وتبين اللائحة التنفيذية لهذا القانون شروط وإجراءات تطبيق أحكام هذه المادة .$m225$,'9c154b87a577280294a65874fd091b75'),
(9,0,$m225$المادة 9$m225$,$m225$لا تسرى أحكام هذا القانون بالنسبة للمرافق العامة التى تديرها الدولة .
وللجهاز بناء على طلب ذوى الشأن أن يخرج من نطاق الحظر كل أو بعض الأفعال المنصوص عليها فى المواد ( 6 ، 7 ، 8 ) المرافق العامة التى تديرها شركات خاضعة لأحكام القانون الخاص إذا كان من شأن ذلك تحقيق المصلحة العامة أو تحقيق منافع للمستهلك تفوق آثار الحد من حرية المنافسة ، وذلك وفقاً للضوابط والإجراءات التى تحددها اللائحة التنفيذية لهذا القانون .$m225$,'ca9e5848f55335d365dbc8cebcf5a209'),
(10,0,$m225$المادة 10$m225$,$m225$يجوز بقرار من مجلس الوزراء تحديد سعر بيع منتج أساسى أو أكثر لفترة زمنية محددة وذلك بعد أخذ رأى الجهاز .
ولا يعتبر نشاطاً ضاراً بالمنافسة أى اتفاق تبرمه الحكومة بقصد تطبيق الأسعار التى يتم تحديدها .$m225$,'7ce273542064fe4538754bfdb6ff9f92'),
(11,0,$m225$المادة 11$m225$,$m225$ينشأ جهاز يسمى جهاز حماية المنافسة ومنع الممارسات الاحتكارية يكون مقره القاهرة الكبرى وتكون له الشخصية الاعتبارية العامة ، يتبع الوزير المختص ، ويتولى على الأخص ما يلى :
( 1 ) تلقى الطلبات باتخاذ إجراءات التقصى والبحث وجمع الاستدلالات والأمر باتخاذ هذه الإجراءات بالنسبة لحالات الاتفاقات والممارسات الضارة بالمنافسة ، وذلك طبقاً للإجراءات التى تحددها اللائحة التنفيذية لهذا القانون .
( 2 ) تلقى الإخطارات من الأشخاص ، فور اكتسابها أى أصول أو حقوق ملكية أو انتفاع أو أسهم ، أو إقامة اتحادات أو اندماجات أو دمج ، أو الجمع بين إدارة شخصين أو أكثر .
وتحدد اللائحة التنفيذية لهذا القانون ميعاد وبيانات الإخطار والمستندات التى يجب إرفاقها به وإجراءات تقديمه .
( 3 ) إعداد قاعدة بيانات ومعلومات متكاملة عن النشاط الاقتصادى وتحديثها وتطويرها بصورة دائمة بما يخدم عمل الجهاز فى كافة المجالات المرتبطة بحماية المنافسة .
وإنشاء قاعدة بيانات وإجراء الدراسات والبحوث اللازمة لكشف الحالات الضارة بالمنافسة .
( 4 ) اتخاذ التدابير المنصوص عليها فى المادة ( 20 ) من هذا القانون .
( 5 ) إبداء الرأى فى مشروعات القوانين واللوائح المتعلقة بتنظيم المنافسة .
( 6 ) التنسيق مع الأجهزة النظيرة فى الدول الأخرى بالنسبة للأمور ذات الاهتمام المشترك .
( 7 ) تنظيم برامج تدريبية وتثقيفية بهدف التوعية بأحكام هذا القانون ومبادئ السوق الحرة بوجه عام .
( 8 ) إصدار نشرة دورية تتضمن القرارات والتوصيات والإجراءات والتدابير التى يتخذها الجهاز وغير ذلك مما يتصل بشئونه .
( 9 ) إعداد تقرير سنوى عن أنشطة الجهاز وخطته المستقبلية ومقترحاته ليعرض على الوزير المختص بعد اعتماده من مجلس الإدارة ، وترسل نسخة منه إلى مجلسى الشعب والشورى .
وتحدد اللائحة التنفيذية لهذا القانون الإجراءات التى يتبعها الجهاز لتحقيق وإثبات الأفعال التى تتضمن أو تشكل مخالفة لأحكام هذا القانون .$m225$,'a0fc7f71a38160e5dceee2f936b8dbd3'),
(12,0,$m225$المادة 12$m225$,$m225$يتولى إدارة الجهاز مجلس إدارة يصدر بتشكيله قرار من الوزير المختص ، وذلك على الوجه الآتى :
( 1 ) رئيس متفرغ من ذوى الخبرة المتميزة .
( 2 ) مستشار من مجلس الدولة بدرجة نائب رئيس يختاره رئيس مجلس الدولة .
( 3 ) أربعة يمثلون الوزارات المعنية يرشحهم الوزير المختص .
( 4 ) ثلاثة من المتخصصين وذوى الخبرة .
( 5 ) ستة يمثلون الاتحاد العام للغرف التجارية واتحاد الصناعات المصرية واتحاد البنوك والاتحاد العام للجمعيات الأهلية والاتحاد العام لحماية المستهلك والاتحاد العام لعمال مصر ، على أن يختار كل اتحاد من يمثله .
وتكون مدة المجلس أربع سنوات قابلة للتجديد لمدة واحدة .
ويتضمن قرار التشكيل تحديد المعاملة المالية لرئيس وأعضاء المجلس .$m225$,'d8c5b1a94c495d55b3d0d680d9a8d327'),
(13,0,$m225$المادة 13$m225$,$m225$يجتمع المجلس بدعوة من رئيسه مرة على الأقل كل شهر وكلما دعت الضرورة ، وتكون اجتماعاته صحيحة بحضور عشرة من أعضائه ، وتصدر قراراته بأغلبية أعضائه .
ولا يجوز لأى عضو فى المجلس أن يشارك فى المداولات أو التصويت فى حالة معروضة على المجلس تكون له فيها مصلحة أو بينه وبين أحد أطرافها صلة قرابة إلى الدرجة الرابعة أو يكون قد مثل أو يمثل أحد الأطراف .
وللمجلس أن يدعو لحضور اجتماعاته من يرى الاستعانة به من المتخصصين ، وذلك دون أن يكون له صوت معدود فى التصويت .
وتحدد اللائحة التنفيذية اختصاصات المجلس بما يتفق مع أحكام هذا القانون وإجراءات الدعوة إلى اجتماعاته ونظام العمل فيه .$m225$,'d3339be069e22c0af713c2aa559261b6'),
(14,0,$m225$المادة 14$m225$,$m225$يكون للجهاز موازنة مستقلة تعد على نمط موازنات الهيئات العامة الخدمية ويرحل الفائض منها من سنة مالية إلى أخرى ، وتتكون موارد الجهاز مما يأتى :
( 1 ) ما يخصص للجهاز فى الموازنة العامة للدولة .
( 2 ) المنح والهبات وأية موارد أخرى يقبلها مجلس إدارة الجهاز بما لا يتعارض مع أهدافه .
( 3 ) حصيلة الرسوم المنصوص عليها فى هذا القانون .$m225$,'eb74e0716a2a561e1abdec49b90b1870'),
(15,0,$m225$المادة 15$m225$,$m225$يكون للجهاز مدير تنفيذى متفرغ يصدر بتعيينه وبتحديد معاملته المالية واختصاصاته قرار من الوزير المختص بناء على ترشيح من رئيس الجهاز .
ويمثل المدير التنفيذى الجهاز لدى الغير وأمام القضاء .
ويحضر المدير التنفيذى اجتماعات مجلس الإدارة دون أن يكون له صوت معدود .
ويضع مجلس إدارة الجهاز اللوائح المتعلقة بتنظيم العمل فيه وبالشئون المالية والإدارية للعاملين به دون التقيد بالقواعد والنظم المقررة للعاملين المدنيين بالدولة ، وتصدر هذه اللوائح بقرار من الوزير المختص .$m225$,'c83cf0fb09d0952aaefd5d85fa362318'),
(16,0,$m225$المادة 16$m225$,$m225$يحظر على العاملين بالجهاز إفشاء المعلومات أو البيانات المتعلقة بالحالات الخاصة بتطبيق أحكام هذا القانون أو الكشف عن مصادرها ، والتى يتم تقديمها أو تداولها أثناء فحص هذه الحالات واتخاذ الإجراءات وإصدار القرارات الخاصة بها .
ولا يجوز استخدام هذه المعلومات والبيانات ومصادرها لغير الأغراض التى قدمت من أجلها .
ويحظر على العاملين بالجهاز القيام بأى عمل ، لمدة عامين من تاريخ تركهم للخدمة ، لدى الأشخاص الذين خضعوا للفحص أو الخاضعين له فى ذلك التاريخ .$m225$,'3fcebf891cb3bb0eb0fac339acff96a5'),
(17,0,$m225$المادة 17$m225$,$m225$يكون للعاملين بالجهاز الذين يصدر بتحديدهم قرار من وزير العدل بالاتفاق مع الوزير المختص بناء على اقتراح المجلس صفة الضبطية القضائية فى تطبيق أحكام هذا القانون .
ويكون لهؤلاء العاملين الحق فى الاطلاع لدى أية جهة حكومية أو غير حكومية على الدفاتر والمستندات والحصول على المعلومات والبيانات اللازمة لفحص الحالات المعروضة على الجهاز .$m225$,'0477f0e07a92f25cb818bb46aabe33ed'),
(18,0,$m225$المادة 18$m225$,$m225$تحدد اللائحة التنفيذية لهذا القانون فئات الرسوم التى يستحقها الجهاز مقابل ما يؤديه من خدمات ، وذلك بما لا يجاوز عشرة آلاف جنيه لكل حالة .$m225$,'c900a866b8e4fc4efe46baf24906e260'),
(19,0,$m225$المادة 19$m225$,$m225$يجوز لأى شخص إبلاغ الجهاز بأية مخالفة تقع لأحكام هذا القانون .$m225$,'31ca95c46212e1a4e5257a7619e875c9'),
(20,0,$m225$المادة 20$m225$,$m225$على الجهاز عند ثبوت مخالفة أحد الأحكام الواردة بالمواد ( 6 ، 7 ، 8 ) من هذا القانون تكليف المخالف بتعديل أوضاعه وإزالة المخالفة فوراً ، أو خلال فترة زمنية يحددها مجلس إدارة الجهاز وإلا وقع الاتفاق أو التعاقد المخالف للمادتين ( 6 ، 7 ) من هذا القانون باطلاً .
وللمجلس أن يصدر قراراً بوقف الممارسات المحظورة فوراً ، أو بعد انقضاء الفترة الزمنية المشار إليها دون تعديل الأوضاع وإزالة المخالفة .
وذلك كله دون الإخلال بأحكام المسئولية الناشئة عن هذه المخالفات .$m225$,'727b54858a5e53bbed0bcc442c443164'),
(21,0,$m225$المادة 21$m225$,$m225$لا يجوز رفع الدعوى الجنائية أو اتخاذ إجراءات فيها بالنسبة إلى الأفعال المخالفة لأحكام هذا القانون إلا بطلب كتابى من الوزير المختص أو من يفوضه .
وللوزير المختص أو من يفوضه التصالح فى أى من تلك الأفعال قبل صدور حكم بات فيها ، وذلك مقابل أداء مبلغ لا يقل عن مثلى الحد الأدنى للغرامة ولا يجاوز مثلى حدها الأقصى .
ويعتبر التصالح بمثابة تنازل عن طلب رفع الدعوى الجنائية ويترتب عليه انقضاء الدعوى الجنائية عن ذات الواقعة التى صدر بشأنها طلب رفع الدعوى .$m225$,'7fa145785c646e666bbe6c2a26296ddd'),
(22,0,$m225$المادة 22$m225$,$m225$مع عدم الإخلال بأية عقوبة أشد ينص عليها أى قانون آخر يعاقب على كل مخالفة لأحكام أى من المواد ( 6 ، 7 ، 8 ) من هذا القانون بغرامة لاتقل عن ثلاثين ألف جنيه ولا تجاوز عشرة ملايين جنيه .
وللمحكمة بدلاً من الحكم بالمصادرة أن تقضى بغرامة بديلة تعادل قيمة المنتج محل النشاط المخالف .$m225$,'77c861d733f13864987d31f12f467ebf'),
(23,0,$m225$المادة 23$m225$,$m225$مع عدم الإخلال بأية عقوبة أشد ينص عليها أى قانون آخر يعاقب على مخالفة أى من أحكام المادة ( 16 ) من هذا القانون بغرامة لاتقل عن عشرة آلاف جنيه ولاتجاوز خمسين ألف جنيه .$m225$,'bd63c1dc2b0937f5027e60861ca96216'),
(24,0,$m225$المادة 24$m225$,$m225$يحكم بنشر الأحكام النهائية الصادرة بالإدانة فى الأفعال المشار إليها فى المادة ( 22 ) من هذا القانون فى الجريدة الرسمية وفى جريدتين يوميتين واسعتى الانتشار على نفقة المحكوم عليه .$m225$,'fe0beb202d9d39307a2b175e6e902138'),
(25,0,$m225$المادة 25$m225$,$m225$يعاقب المسئول عن الإدارة الفعلية للشخص الاعتبارى المخالف بذات العقوبات المقررة عن الأفعال التى ترتكب بالمخالفة لأحكام هذا القانون ، إذا ثبت علمه بها وكان إخلاله بالواجبات التى تفرضها عليه تلك الإدارة قد أسهم فى وقوع الجريمة .
ويكون الشخص الاعتبارى مسئولاً بالتضامن عن الوفاء بما يحكم به من عقوبات مالية وتعويضات إذا كانت المخالفة قد ارتكبت من أحد العاملين به باسم الشخص الاعتبارى أو لصالحه .$m225$,'ad67967961615b26c568790057c12684');

DO $m225$
DECLARE
  v_law uuid;
  v_title text;
  v_new_law boolean := false;
  v_ins_art int;
  v_ins_ver int;
  v_cnt int;
  v_nover int;
BEGIN
  IF (SELECT count(*) FROM m225_art WHERE md5(body) <> body_md5) <> 0 THEN
    RAISE EXCEPTION '[225] تلف فى نص أحد الصفوف داخل الملف';
  END IF;
  IF (SELECT count(*) FROM m225_art) <> 30 OR (SELECT sum(char_length(body)) FROM m225_art) <> 11135 THEN
    RAISE EXCEPTION '[225] عدد الصفوف أو طول النص داخل الملف غير مطابق';
  END IF;

  SELECT id, title INTO v_law, v_title FROM laws WHERE country_code='EG' AND law_no=3 AND law_year=2005 AND kind='law';
  IF v_law IS NOT NULL AND v_title NOT LIKE '%المنافسة%' THEN
    RAISE EXCEPTION '[225] يوجد مستند آخر برقم 3 لسنة 2005 (%): لا يُدمج هذا القانون فيه', v_title;
  END IF;
  IF v_law IS NULL THEN
    INSERT INTO laws (law_no, law_year, title, short_title, category, status, official_url, enacted_at, last_amended_at, country_code, kind, governance_scope)
    VALUES (3, 2005, $t225$القانون رقم 3 لسنة 2005 بإصدار قانون حماية المنافسة ومنع الممارسات الاحتكارية (النص الأصلى المنشور فى 15/2/2005 قبل تعديلاته)$t225$, $t225$قانون حماية المنافسة ومنع الممارسات الاحتكارية 3/2005$t225$, 'other', 'amended', NULL, DATE '2005-02-15', NULL, 'EG', 'law', false)
    RETURNING id INTO v_law;
    v_new_law := true;
  END IF;

  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, body)
  SELECT v_law, article_no, suffix, loc, body FROM m225_art
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING;
  GET DIAGNOSTICS v_ins_art = ROW_COUNT;

  INSERT INTO article_versions (article_id, version_no, body, effective_from, status, change_note)
  SELECT a.id, 1, a.body, DATE '2005-05-16', 'active', $n225$النص الأصلى كما نشر فى الجريدة الرسمية العدد 6 مكرر فى 15/2/2005؛ عدل القانون لاحقا (القانونان 190 لسنة 2008 و175 لسنة 2022 بحسب ملاحظات المشروع) ونصوص التعديلات لم ترفع بعد، فقد لا يطابق هذا النص الصيغة النافذة حاليا$n225$
    FROM articles a JOIN m225_art m ON m.article_no = a.article_no AND m.suffix = a.article_suffix_order
   WHERE a.law_id = v_law
     AND NOT EXISTS (SELECT 1 FROM article_versions v WHERE v.article_id = a.id)
  ON CONFLICT (article_id, version_no) DO NOTHING;
  GET DIAGNOSTICS v_ins_ver = ROW_COUNT;

  SELECT count(*) INTO v_cnt FROM articles a JOIN m225_art m ON m.article_no=a.article_no AND m.suffix=a.article_suffix_order
   WHERE a.law_id=v_law;
  IF v_cnt <> 30 THEN
    RAISE EXCEPTION '[225] عدد صفوف القانون % بدل 30', v_cnt;
  END IF;
  SELECT count(*) INTO v_nover FROM articles a
   WHERE a.law_id=v_law AND NOT EXISTS (SELECT 1 FROM article_versions v WHERE v.article_id=a.id);
  IF v_nover <> 0 THEN
    RAISE EXCEPTION '[225] % صف بلا نسخة', v_nover;
  END IF;
  RAISE NOTICE '[225] قانون 3/2005: جديد=%، صفوف مضافة=%، نسخ مضافة=%', v_new_law, v_ins_art, v_ins_ver;
END
$m225$;
